function GlobalRail({navigate}){return <nav className="global-rail" aria-label="全局工具"><div><button aria-label="菜单"><ListChecks/></button><button aria-label="首页" onClick={()=>navigate("overview")}><House/></button><button aria-label="全局搜索"><MagnifyingGlass/></button><button aria-label="通知"><Bell/><i>2</i></button><button aria-label="工作应用"><Gauge/></button><button aria-label="资料空间" onClick={()=>navigate("materials")}><HardDrive/></button></div><div><button aria-label="系统保障"><ShieldCheck/></button><button aria-label="当前用户"><UserCircle/></button></div></nav>}
function Sidebar({active,navigate}){return <aside className="sidebar"><div className="brand"><div><strong>专业群 AI 工作站</strong><span>建设管理与协同办理</span></div><button aria-label="收纳菜单"><CaretDown/></button></div><p className="nav-label">建设工作台</p><nav>{navItems.map(({id,icon:Icon,label,badge})=><button key={id} className={active===id?"active":""} onClick={()=>navigate(id)}><Icon size={17} weight={active===id?"fill":"regular"}/><span>{label}</span>{badge&&<b>{badge}</b>}</button>)}</nav><p className="nav-label secondary-label">项目与保障</p><div className="sidebar-links"><button onClick={()=>navigate("organization")}><Buildings/><span>人工智能专业群</span></button><button onClick={()=>navigate("materials")}><HardDrive/><span>学校资料空间</span></button><button onClick={()=>navigate("pilot")}><ShieldCheck/><span>试点与验收安排</span></button></div><div className="sidebar-bottom"><div className="data-rights"><HardDrive size={16}/><div><strong>学校资料空间</strong><span>完整权利与控制权</span></div></div><div className="current-user"><UserCircle size={25} weight="fill"/><div><strong>人工智能专业群</strong><span>2026—2028 建设周期</span></div><CaretDown/></div></div></aside>}
function Topbar({active}){return <header className="topbar"><div className="breadcrumb"><span>专业群 AI 工作站</span><CaretRight/><strong>{active}</strong></div><label className="search"><MagnifyingGlass/><input placeholder="搜索任务、指标、材料或教师…"/></label><div className="header-actions"><span className="period"><CalendarBlank/>2026 年度</span><button>保存草稿</button><button className="primary">提交审核</button></div></header>}
function WorkflowNav({active,navigate}){const activeNode=flowParent[active]||active;const currentIndex=flowSteps.findIndex(step=>step.id===activeNode);return <section className="workflow-nav" aria-label="当前建设工作办理链"><div className="workflow-caption"><span>当前办理链</span><strong>新增合作企业 3 家</strong><small>{active==="overview"?"从建设依据开始连续办理":"可直接进入前后节点"}</small></div><div className="workflow-steps">{flowSteps.map((step,index)=><button key={step.id} className={`${activeNode===step.id?"active":""} ${currentIndex>index||step.state==="已就绪"?"ready":""}`} onClick={()=>navigate(step.id)}><b>{step.no}</b><span><strong>{step.label}</strong><small>{step.state}</small></span>{index<flowSteps.length-1&&<CaretRight/>}</button>)}</div>{active==="overview"&&<button className="workflow-start" onClick={()=>navigate("basis")}>开始办理<CaretRight/></button>}</section>}
function StatStrip(){return <section className="stat-strip"><div className="project-status"><Gauge size={22} weight="fill"/><div><strong>人工智能专业群</strong><span>2026—2028 建设周期</span></div><em>演示样例</em></div>{stats.map(s=><article key={s.label} className={s.tone}><strong>{s.value}</strong><div><span>{s.label}</span><small>{s.note}</small></div></article>)}</section>}
function AssistantBar({prompt,setPrompt,response,submit}){return <><section className="assistant-bar"><div className="assistant-icon"><Sparkle weight="fill"/></div><div className="assistant-name"><strong>专业群助手</strong><span>进度查询 · 材料检索 · 任务办理</span></div><input value={prompt} onChange={e=>setPrompt(e.target.value)} onKeyDown={e=>e.key==="Enter"&&submit()} placeholder="例如：按任务书逐条看，还有哪些指标没有达到要求？"/><button onClick={submit}>提交给助手 <PaperPlaneTilt weight="fill"/></button><div className="quick-prompts">{quickPrompts.map(x=><button key={x} onClick={()=>setPrompt(x)}>{x}</button>)}</div></section>{response&&<div className="assistant-response"><Sparkle weight="fill"/><strong>助手已接收：</strong><span>{response}</span><button onClick={()=>setPrompt("")}>继续追问</button></div>}</>}
function PageIntro({eyebrow,title,description,children}){return <section className="page-intro"><div><span>{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{children&&<aside>{children}</aside>}</section>}
function PageFrame({children}){return <main className="page-content">{children}</main>}
function ManageActions({primary,secondary,note}){const [message,setMessage]=useState("");return <section className="manage-actions"><div><NotePencil weight="fill"/><span><strong>栏目维护</strong><small>{note}</small></span></div><button onClick={()=>setMessage(`已进入“${secondary}”操作区`)}>{secondary}</button><button className="primary" onClick={()=>setMessage(`已进入“${primary}”编辑区`)}>{primary}<CaretRight/></button>{message&&<em><CheckCircle weight="fill"/>{message}</em>}</section>}

function RoleRail(){return <aside className="role-rail"><div className="panel-title"><span>责任协作</span><small>谁负责确认</small></div>{roles.slice(1,5).map(r=><article key={r.name} className={r.tone}><div className="role-avatar">{r.initials}</div><strong>{r.name}</strong><span>{r.state}</span></article>)}<div className="role-rule"><ShieldCheck/><span>助手整理建议<br/><b>学校人员确认</b></span></div></aside>}
function TaskFlow({filter,setFilter,selected,setSelected}){const filters=[["all","全部"],["doing","推进中"],["confirm","待确认"],["blocked","材料不足"],["done","已完成"]];const visible=filter==="all"?tasks:tasks.filter(t=>t.statusKey===filter);return <main className="task-flow"><div className="flow-heading"><div><span>建设任务流</span><h2>当前需要推进的工作</h2></div><div className="filters">{filters.map(([key,label])=><button className={filter===key?"active":""} onClick={()=>setFilter(key)} key={key}>{label}<b>{key==="all"?tasks.length:tasks.filter(t=>t.statusKey===key).length}</b></button>)}</div></div><div className="task-list">{visible.map(task=><button className={`task-card ${task.statusKey} ${selected.id===task.id?"selected":""}`} key={task.id} onClick={()=>setSelected(task)}><div className="task-top"><span className="task-id">{task.id}</span><h3>{task.title}</h3><em>{task.status}</em></div><div className="progress-track"><i style={{width:`${task.progress}%`}}/></div><div className="task-meta"><span><UserCircle weight="fill"/>{task.owner}</span><span className={task.statusKey==="blocked"?"urgent":""}><Clock/>{task.deadline}</span></div><div className="task-tags">{task.tags.map(tag=><span key={tag}>{tag}</span>)}<CaretRight/></div></button>)}{visible.length===0&&<div className="empty-state"><CheckCircle size={34}/><strong>当前筛选下没有任务</strong><span>可以切换状态查看其他建设事项。</span></div>}</div><button className="history-row"><ArrowsClockwise/><strong>历史任务与版本</strong><span>本年度 32 项记录 · 7 次口径确认 · 5 份成果版本</span><CaretRight/></button></main>}
function EvidenceRail(){return <aside className="evidence-rail"><div className="panel-title"><span>指标与材料</span><small>结论从哪里来</small></div><div className="metric-card"><span>年度示例指标</span><strong>新增合作企业 3 家</strong><div><b>1</b><small>已确认</small><i/><b className="gap">2</b><small>尚差</small></div></div><div className="evidence-list">{evidence.map(e=><article key={e.code} className={e.tone}><b>{e.code}</b><div><strong>{e.name}</strong><span>{e.state}</span></div><em>{e.result}</em></article>)}</div><div className="evidence-summary"><ClipboardText/><div><strong>材料状态</strong><span>正式材料 4 · 过程材料 6 · 待补 1</span></div></div></aside>}
function ReviewPanel({task}){return <aside className="review-panel"><div className="review-head"><div><span>当前任务详情</span><h2>{task.id} · {task.status}</h2></div><button aria-label="详细说明"><Info/></button></div><section className="focus-task"><div className={`focus-icon ${task.statusKey}`}>{task.statusKey==="done"?<CheckCircle weight="fill"/>:task.statusKey==="blocked"?<WarningCircle weight="fill"/>:<TrendUp weight="fill"/>}</div><div><strong>{task.title}</strong><p>{task.note}</p></div></section><div className="review-section"><div className="section-label"><span>事实判断</span><small>截至演示统计期</small></div>{evidence.map(e=><div className="judgement" key={e.code}><span className={e.tone}>{e.code}</span><div><strong>{e.result}</strong><small>{e.state}</small></div>{e.result==="计入 1 家"?<CheckCircle className="ok" weight="fill"/>:e.tone==="red"?<XCircle className="bad" weight="fill"/>:<WarningCircle className="warn" weight="fill"/>}</div>)}</div><div className="review-section next-step"><div className="section-label"><span>助手建议的下一步</span><small>需负责人确认</small></div><p>{task.next}</p><button><ListChecks/>生成后续任务清单</button></div><div className="review-section reusable"><div className="section-label"><span>可沉淀的工作方法</span><small>内部候选</small></div><article><Books/><div><strong>年度新增成果判断规则</strong><span>年度、正式材料、有效活动三项同时核对</span></div></article><article><FileText/><div><strong>指标对照说明模板</strong><span>目标—实际—证据—差距—下一步</span></div></article></div></aside>}
const roleWork={
  teacher:{label:"教师",name:"李老师",summary:"填写进展、补充资料和处理退回",items:[{title:"推进 B 企业正式签约",meta:"T07 · 今天 17:00",action:"填写进展",tone:"urgent"},{title:"B 企业协议草稿被退回",meta:"请补正式签订版和签订日期",action:"处理退回",tone:"returned"},{title:"课程共建研讨记录",meta:"助手已整理，等待你确认关系",action:"确认关系",tone:"normal"}]},
  leader:{label:"专业群负责人",name:"周老师",summary:"分解任务、核对事实和确认结果",items:[{title:"核对 B 企业补充材料",meta:"李老师已提交修订说明",action:"审核资料",tone:"urgent"},{title:"确认新增合作企业阶段结论",meta:"A—D 企业 · 截至 6 月 30 日",action:"确认结论",tone:"normal"},{title:"为 D 企业指定牵头教师",meta:"T07 · 本周内完成",action:"安排任务",tone:"normal"}]},
  reviewer:{label:"教务审核",name:"陈老师",summary:"统一口径、审核成果和确认正式版本",items:[{title:"审核年度报告第三部分",meta:"第三轮草稿 · 3 处待确认",action:"进入审核",tone:"urgent"},{title:"处理企业材料年份冲突",meta:"C 企业 · 2025 / 2026 口径",action:"核对冲突",tone:"returned"},{title:"确认指标—证据目录",meta:"本月版本 v3",action:"确认版本",tone:"normal"}]},
};

